function export:f_7_BuddyUnlock_Completed()
	self = self._graph;
	-- Regenerate buddies only if a library mission isn't active (update 3.1: added BSQ check and buddy regeneration)
	if (Globals.MASTER_GameGlobals.PrimaryMissionActive == 0) and (Globals.MASTER_GameGlobals.AcceptedBuddyMissionID == "x") then
		Boxes[PathID("Domino/System/LogToConsole.lua")].Integer = nil;
		Boxes[PathID("Domino/System/LogToConsole.lua")].Float = nil;
		Boxes[PathID("Domino/System/LogToConsole.lua")].Boolean = nil;
		Boxes[PathID("Domino/System/LogToConsole.lua")].String = "MikesPlace : New unlocked buddy for current mode";
		Boxes[PathID("Domino/System/LogToConsole.lua")].Entity = nil;
		Boxes[PathID("Domino/System/LogToConsole.lua")]._graph = self;
		Boxes[PathID("Domino/System/LogToConsole.lua")].Out = self._type.f_8_Out;
		Boxes[PathID("Domino/System/LogToConsole.lua")]._type.In(Boxes[PathID("Domino/System/LogToConsole.lua")]);
	-- Update 3.2: Don't de-spawn buddies if a BSQ mission is active
	--else
	elseif (Globals.MASTER_GameGlobals.AcceptedBuddyMissionID == "x") then
		-- Regenerate buddies excluding primary (library mission subversion) buddy
		self.MikesPlace_PawnsReady = false;
		self._type.en_63_PrimaryCheck(self);
		self[63]._type.Instant_remove(self[63]);
	end
end;

