function export:en_63_PrimaryCheck()
	self[63].Marty = self.Entity_MartyAlencar;
	self[63].Flora = self.Entity_FloraGuillen;
	self[63].Warren = self.Entity_WarrenClyde;
	self[63].Josip = self.Entity_JosipIdromeno;
	self[63].Paul = self.Entity_PaulFerenc;
	self[63].Quarbani = self.Entity_QuarbaniSingh;
	self[63].Michele = self.Entity_MicheleDachss;

	-- Prevent despawning library mission (subversion) buddy
	if (GetBuddiesManager():GetPrimaryBuddyName() == "Marty_Alencar") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[63].Marty = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Flora_Guillen") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[63].Flora = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Warren_Clyde") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[63].Warren = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Josip_Idromeno") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[63].Josip = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Paul_Ferenc") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[63].Paul = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Quarbani_Singh") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[63].Quarbani = nil;
	elseif (GetBuddiesManager():GetPrimaryBuddyName() == "Michele_Dachss") and (Globals.MASTER_GameGlobals.PrimaryMissionActive == 1) then
		self[63].Michele = nil;
	end
end;

